import java.io.*;import java.util.*;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);int t = Integer.parseInt(br.readLine());while (t-- > 0) {int n = Integer.parseInt(br.readLine());StringTokenizer st = new StringTokenizer(br.readLine());Map<Integer, Long> counts = new HashMap<>();long totalPairs = 0;for (int i = 0; i < n; i++) {int val = Integer.parseInt(st.nextToken()) - i;long count = counts.getOrDefault(val, 0L);totalPairs += count;counts.put(val, count + 1);}out.println(totalPairs);}out.flush();out.close();}}